package ai.taskforge.api; import ai.taskforge.domain.*; import ai.taskforge.repo.NotificationRepository; import ai.taskforge.service.CurrentUser; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController { private final NotificationRepository notifications;private final CurrentUser current;public NotificationController(NotificationRepository n,CurrentUser c){notifications=n;current=c;} record View(UUID id,String type,String message,boolean read,java.time.Instant createdAt){} @GetMapping List<View> list(){return notifications.findByRecipientIdOrderByCreatedAtDesc(current.get().getId()).stream().map(n->new View(n.getId(),n.getType(),n.getMessage(),n.isRead(),n.getCreatedAt())).toList();} @PostMapping("/{id}/read") View read(@PathVariable UUID id){var n=notifications.findById(id).orElseThrow(()->new ApiException("NOT_FOUND","Notification not found."));n.markRead();n=notifications.save(n);return new View(n.getId(),n.getType(),n.getMessage(),n.isRead(),n.getCreatedAt());} }
